//! An infinite rolling deck: periodic card identities, continuous motion coordinates.
use crate::{widgets::Ui,model::{Model,Page,Action},draw::{self,rect,Icon},views::{self,ViewState}};
use vello::{kurbo::Affine,peniko::Mix};
use serde_json::json;
pub use dotisle_domain::card_ring::{self as ring,STEP};
pub const TITLES:[&str;5]=["音乐","专注","待办","通知中心","桌面组件"];
pub fn render(ui:&mut Ui,m:&Model,x:f64,_y:f64,w:f64,state:&ViewState)->f64{
 let x=x+(w-w.min(980.))/2.;let w=w.min(980.);let clip=ui.clip;let top=clip.y0+54.;let h=(clip.height()-128.).clamp(280.,332.);let progress=ring::phase(m.scroll);
 let base=progress.floor()as i64;let mut order=(base-2..=base+5).collect::<Vec<_>>();order.sort_by(|a,b|((*b as f64-progress).abs()).total_cmp(&(*a as f64-progress).abs()));
 for slot in order{let i=ring::slot_index(slot);let d=slot as f64-progress;let visibility=(2.-d.abs()).clamp(0.,1.);if visibility<=0.{continue}let dy=if d<0.{d*46.}else if d<=1.{d*(h-24.)}else{h-24.+(d-1.)*64.};let scale=1.-0.035*d.abs().min(3.);let tx=x+w*(1.-scale)/2.;let ty=top+dy;let visual_h=if d.abs()>=1.{72.}else{h+(72.-h)*d.abs().powi(3)};let bounds=rect(tx,ty,w*scale,visual_h*scale);if bounds.y1<clip.y0||bounds.y0>clip.y1{continue}
  let tr=Affine::translate((tx,ty))*Affine::scale(scale);let inverse=tr.inverse();let pointer=ui.pointer;let old=std::mem::take(ui.scene);let start=ui.hits.len();ui.pointer=(inverse*vello::kurbo::Point::from(pointer)).into();ui.clip=inverse.transform_rect_bbox(clip);
  let s=ui.s;let bg=match i{0=>s.primary_container,1=>s.tertiary_container,4=>s.secondary_container,_=>s.container};let depth=d.abs().min(1.);let bg=mix(bg,s.surface,depth*0.42);let card_h=if d.abs()>=1.{72.}else{h+(72.-h)*d.abs().powi(3)};let r=rect(0.,0.,w,card_h);let front=1.-depth;let radius=if ui.terminal||ui.pixel{0.}else if ui.swiss{22.}else if ui.nocturne{18.}else if ui.nothing{12.}else{28.};
  if front>0.01{ui.scene.draw_blurred_rounded_rect(Affine::translate((0.,3.)),r,draw::alpha(s.on_surface,(0.13*front)as f32),radius,5.);}
  ui.panel(r,bg);draw::outline(ui.scene,r,radius,mix(bg,s.on_surface,if m.prefs.dark{0.24}else{0.14}),1.);
  // Blank space is a direct-manipulation target; child controls take precedence.
  ui.hit(rect(0.,0.,w,h),"上下拖动浏览卡片",Action::OverviewDrag,true);
  let fg=match i{0=>s.on_primary_container,1=>s.on_tertiary_container,4=>s.on_secondary_container,_=>s.on_surface};let body=(1.-d.abs()*1.2).clamp(0.,1.);
  let hy=if d<0.{20.-4.*d.abs().min(1.)}else{20.+d.abs().min(1.)*16.};ui.label(TITLES[i],24.,hy,18.,fg,true,w-48.);
  if body>0.001{ui.scene.push_layer(Mix::Normal,body as f32,Affine::IDENTITY,&rect(0.,60.,w,h-60.));content(ui,m,i,w,h,state);ui.scene.pop_layer();}
  let card=std::mem::replace(ui.scene,old);ui.clip=clip;ui.pointer=pointer;
  let softness=if m.prefs.reduced_motion{0.}else{state.scroll_blur.min(1.5)};if softness>0.05{ui.scene.push_gaussian_layer(Affine::IDENTITY,&clip,softness);}
  if visibility<1.{ui.scene.push_layer(Mix::Normal,visibility as f32,Affine::IDENTITY,&clip);}ui.scene.append(&card,Some(tr));if visibility<1.{ui.scene.pop_layer();}if softness>0.05{ui.scene.pop_layer();}
  if d.abs()>0.46{ui.hits.truncate(start);ui.hit(bounds.intersect(clip),&format!("浏览{}卡片",TITLES[i]),Action::OverviewCard(i),true);}else{for hit in &mut ui.hits[start..]{hit.rect=tr.transform_rect_bbox(hit.rect).intersect(clip);}}
 }
 clip.y1
}
fn content(ui:&mut Ui,m:&Model,i:usize,w:f64,h:f64,state:&ViewState){if i==0&&ui.nocturne{crate::nocturne::music_card(ui,m,w,h,state);return}if i==0&&ui.swiss{crate::swiss::music_card(ui,m,w,h,state);return}let s=ui.s;match i{
 0=>{views::record(ui,m,rect(w-132.,66.,96.,96.),false);ui.label(m.title(),24.,72.,30.,s.on_primary_container,true,w-190.);ui.label(m.artist(),26.,116.,14.,s.on_primary_container,false,w-190.);ui.label(m.current_lyric(),26.,145.,15.,s.on_primary_container,false,w-190.);views::player_controls(ui,m,18.,h-110.,false);views::progress(ui,m,rect(246.,h-98.,w-280.,24.),state);
 ui.label("歌词同步",26.,h-34.,11.,s.on_primary_container,false,66.);ui.icon_button(rect(98.,h-46.,36.,36.),Icon::Back,"歌词提前 100 毫秒",Action::Offset(-100),false,true);ui.center(&format!("{:+} ms",m.prefs.offset_ms),rect(138.,h-46.,88.,36.),12.,s.on_primary_container,true);ui.icon_button(rect(230.,h-46.,36.,36.),Icon::Arrow,"歌词延后 100 毫秒",Action::Offset(100),false,true);ui.button(rect(w-208.,h-48.,184.,36.),"布局与播放组件",Some(Icon::Settings),Action::LayoutOpen,true,true);},
 1=>{let timer=m.current_timer();ui.label(&timer.map(|t|t.clock()).unwrap_or_else(||format!("{:02}:00",m.minutes)),24.,76.,64.,s.on_tertiary_container,true,w-310.);ui.label(&timer.map(|t|t.subtitle()).unwrap_or("番茄钟 · 25 分钟专注，5 分钟休息".into()),28.,163.,13.,s.on_tertiary_container,false,w-56.);let bx=w-254.;ui.button(rect(bx,88.,228.,48.),timer.map(|t|match t.primary_action(){"pause"=>"暂停","resume"=>"继续","next"=>"下一阶段",_=>"重新开始"}).unwrap_or("开始专注"),Some(if timer.is_some_and(|t|t.running){Icon::Pause}else{Icon::Play}),timer.map(|t|Action::Timer(t.id.clone(),t.primary_action())).unwrap_or(Action::QuickFocus),false,true);ui.button(rect(bx,148.,104.,40.),"重置",Some(Icon::Reset),timer.map(|t|Action::Timer(t.id.clone(),"reset")).unwrap_or(Action::Preset(25)),true,timer.is_some());ui.button(rect(bx+116.,148.,112.,40.),"全部计时",None,Action::Navigate(Page::Focus),true,true);if timer.is_none(){for(i,min)in [15,25,45].iter().enumerate(){ui.chip(rect(26.+i as f64*110.,h-62.,100.,38.),&format!("{min} 分钟"),m.minutes==*min,Action::Preset(*min));}}},
 2=>{ui.label(&format!("{} 件未完成",m.pending()),26.,68.,12.,s.on_surface_variant,false,160.);ui.button(rect(w-286.,65.,124.,38.),"快速提醒",None,Action::QuickReminder,true,true);ui.button(rect(w-150.,65.,124.,38.),"添加待办",Some(Icon::Plus),Action::EditTodo(None),false,true);let now=dotisle_domain::todos::Now::local();let mut items=m.todos.items.iter().filter(|t|!t.done(&now)).collect::<Vec<_>>();items.sort_by_key(|t|(&t.date,&t.time));if items.is_empty(){ui.icon(Icon::Leaf,30.,133.,36.,s.primary);ui.label("清爽的一天",88.,126.,24.,s.on_surface,true,w-120.);ui.label("记下一件小事，然后安心去做。",88.,169.,13.,s.on_surface_variant,false,w-120.);}for(i,t)in items.iter().take(2).enumerate(){let y=112.+i as f64*61.;ui.icon_button(rect(18.,y,44.,44.),Icon::Check,"完成待办",Action::ToggleTodo(t.id.clone()),false,true);ui.label(&t.title,78.,y,16.,s.on_surface,true,w-280.);ui.label(&format!("{}  {}{}",t.date,t.time,if t.daily{" · 每天"}else{""}),78.,y+27.,11.,s.on_surface_variant,false,w-280.);ui.button(rect(w-190.,y,90.,38.),"编辑",None,Action::EditTodo(Some(t.id.clone())),true,true);ui.icon_button(rect(w-76.,y,44.,44.),Icon::Trash,"移除待办",Action::DeleteTodo(t.id.clone()),false,true);}ui.button(rect(26.,h-48.,136.,34.),"全部待办",None,Action::Navigate(Page::Todos),true,true);},
 3=>{crate::notification_center::deck(ui,m,0.,64.,w,h-76.);},
 _=>{ui.label("把常用的小事，放在桌面。",26.,78.,24.,s.on_secondary_container,true,w-52.);let kinds=dotisle_domain::desktop_widgets::Kind::ALL;let cw=(w-76.)/3.;for(i,k)in kinds.iter().enumerate(){ui.button(rect(26.+(i%3)as f64*(cw+12.),128.+(i/3)as f64*52.,cw,42.),k.label(),Some(Icon::Plus),Action::WidgetAdd(*k,k.default_size()),true,true);}ui.button(rect(26.,h-48.,192.,34.),"管理已放置的组件",None,Action::Navigate(Page::Widgets),false,true);ui.button(rect(w-202.,h-48.,176.,34.),"灵动岛布局编辑器",None,Action::LayoutOpen,true,true);},
}}
impl Model{pub(crate) fn quick_focus(&mut self){if let Some(t)=self.current_timer(){let a=Action::Timer(t.id.clone(),t.primary_action());self.dispatch(a);return}if self.remote.is_some(){self.native_command("timerCreate",json!({"mode":"pomodoro","focus":self.minutes*60,"rest":self.rest_seconds,"rounds":self.timer_rounds}));}else if self.demo{match self.timers.create(&json!({"mode":"pomodoro","focus":self.minutes*60,"rest":self.rest_seconds,"rounds":self.timer_rounds})){Ok(id)=>self.selected=Some(id),Err(e)=>self.message(e)}}}}

fn mix(a:u32,b:u32,t:f64)->u32{let c=|shift:u32|{let x=((a>>shift)&255)as f64;let y=((b>>shift)&255)as f64;(x+(y-x)*t).round()as u32};c(16)<<16|c(8)<<8|c(0)}
